const paths={person:'<circle cx="24" cy="13" r="7"/><path d="M10 42v-8a14 14 0 0 1 28 0v8M17 42v-8m14 8v-8"/>',bank:'<path d="m5 17 19-11 19 11ZM8 42h32M8 21h32M12 22v15m12-15v15m12-15v15M6 38h36"/>',firm:'<path d="M6 42V22l12 6V17l12 7V7h9l3 35ZM12 34h3m7 0h3m7 0h3"/>',coin:'<circle cx="24" cy="24" r="18"/><path d="m16 15 8 11 8-11M24 26v11m-8-11h16m-16 6h16"/>'};
const icon=k=>`<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]}</svg>`;
const actor=(k,n,s='')=>`<div class="actor">${icon(k)}<b>${n}</b><small>${s}</small></div>`;
const arrow=s=>`<div class="transfer">${s}</div>`;
const card=(h,p,s='')=>`<div class="knowledge-card"><h3>${h}</h3><p>${p}</p>${s?`<small>${s}</small>`:''}</div>`;
const section=(i,h,d,body,take,more='')=>`<section class="chapter" id="step${i}"><span class="number">${i}</span><h2>${h}</h2><p class="description">${d}</p><div class="diagram">${body}</div><p class="take">${take}</p>${more?`<details class="expand"><summary>深入理解与模型边界</summary><p>${more}</p></details>`:''}</section>`;
const titles=['认识货币与财富','贷款如何创造存款','转账与银行结算','生产、收入与消费','利率与借款选择','通胀、供需与购买力','用一个案例串起来'];
const rows=(list)=>list.map(([a,b])=>`<div class="account-row"><span>${a}</span><b>${b}</b></div>`).join('');
document.body.innerHTML=`<header class="top"><div class="brand">${icon('coin')}宏观基础</div><a href="index.html">投资版</a></header><main class="shell"><div class="heading"><span class="eyebrow">UNDERSTAND THE SYSTEM</span><h1>先认识钱，再看懂经济</h1><p>从账户中的一笔存款出发，区分金融记账、真实生产与价格变化。</p></div><div class="page"><nav class="toc" aria-label="知识顺序"><strong>基础知识 · 七个相连的问题</strong>${titles.map((t,i)=>`<a href="#step${i+1}"><span>${i+1}</span>${t}</a>`).join('')}<div class="divider"></div><a href="money.html">货币专题</a><a href="rates.html">利率专题</a><a href="inflation.html">通胀专题</a></nav><article class="story"><div class="origin"><b>阅读这页时，始终分清两件事。</b><p>账户里的钱和债务怎样变，是金融变化；面包、设备和劳动怎样变，是实际经济变化。两者有关，但不能画成一条必然发生的流水线。</p></div>
${section(1,'账户里有钱，不等于拥有同样多的净财富','先认识四个词。货币是支付手段，财富还包括房屋、设备等资产；计算净财富时，需要扣掉债务。',`<div class="knowledge-grid">${card('现金','公众手中的纸币、硬币，可直接用于支付。','在不同国家，纸币和硬币的发行安排可能不同。')}${card('银行存款','银行账户中的可用余额，是持有人的资产，也是银行的负债。','本文主要以可支付的活期存款为例。')}${card('资产','现金、存款、房屋、设备等具有经济价值的资源。','“货币”与“资产”不是同义词。')}${card('债务','未来需要偿还的义务，例如贷款本金。','净财富 = 资产 − 负债。')}</div><div class="total-strip"><span>借入 <b>¥10,000</b></span><span>存款 <b>+¥10,000</b></span><span>债务 <b>+¥10,000</b></span><span>借款瞬间净财富变化 <b>¥0</b></span></div>`,'获得贷款增加了支付能力，也增加了还款义务，不能把借来的钱当作新增净财富。')}
${section(2,'商业银行放贷时，贷款和存款同时出现','我们观察一家银行向面包店新增 10,000 元贷款。这里只追踪这笔新增业务，不表示银行原来没有其他资产和负债。',`<div class="lane">${actor('bank','商业银行','记入贷款与存款')}${arrow('批准贷款 ¥10,000')}${actor('firm','面包店','得到存款，也承担债务')}</div><div class="controls"><span>观察前后两本账</span><button id="before" aria-pressed="true">发放前</button><button id="after" aria-pressed="false">发放后</button><button id="repay" aria-pressed="false">全额偿还本金</button></div><div class="knowledge-grid" style="margin-top:16px"><div class="knowledge-card"><h3>银行的账</h3>${rows([['新增贷款资产','<span id="bankLoan">¥0</span>'],['新增存款负债','<span id="bankDeposit">¥0</span>']])}</div><div class="knowledge-card"><h3>面包店的账</h3>${rows([['新增存款资产','<span id="shopDeposit">¥0</span>'],['新增贷款债务','<span id="shopDebt">¥0</span>']])}</div></div><p class="explanation" id="loanExplain" aria-live="polite">发放前：本例的新增贷款和新增存款均为零。</p>`,'贷款可以创造存款；用存款偿还本金时，对应贷款和存款一起减少。利息不在这幅记账图中。','商业银行不能无限放贷：资本、流动性、监管、信用风险与借款需求都形成约束。央行提供现金与银行准备金；准备金主要用于银行间结算。不要将准备金简单理解为银行按固定倍数反复放大的原料。')}
${section(3,'转账通常改变钱的归属，不再创造一笔钱','面包店给员工转 2,000 元。先看同一家银行内部：一个账户减少，另一个账户增加，合计不变。',`<div class="lane">${actor('firm','面包店','存款 ¥10,000 → ¥8,000')}${arrow('支付工资 ¥2,000')}${actor('person','员工','存款 ¥0 → ¥2,000')}</div><div class="total-strip">两人存款合计：<b>¥10,000 → ¥10,000</b></div><details class="expand"><summary>如果员工在另一家银行开户，会发生什么？</summary><div class="lane" style="margin-top:14px">${actor('bank','银行 A','付款方银行')}${arrow('准备金结算 ¥2,000')}${actor('bank','银行 B','收款方银行')}</div><p>银行 A 扣减面包店存款，银行 B 增加员工存款。银行之间通过准备金完成结算。本图简化为单笔全额结算，实际支付系统可采用净额清算等安排。</p></details>`,'贷款是“新增存款”的情形；转账是“转移存款”的情形。跨行转账还涉及银行之间的结算。')}
${section(4,'商品、劳动与钱，沿着不同方向流动','面包店雇员工制作面包，再出售给居民。工资和销售收入是支付流；劳动和面包是实际资源与产出。',`<div class="flowline realflow"><span class="flowlabel">劳动流</span><div class="lane">${actor('person','员工')}${arrow('提供劳动')}${actor('firm','面包店')}</div></div><div class="flowline cashflow"><span class="flowlabel">工资流</span><div class="lane">${actor('firm','面包店')}${arrow('支付工资')}${actor('person','员工')}</div></div><div class="flowline realflow"><span class="flowlabel">商品流</span><div class="lane">${actor('firm','面包店')}${arrow('交付面包')}${actor('person','居民')}</div></div><div class="flowline cashflow"><span class="flowlabel">消费支付</span><div class="lane">${actor('person','居民')}${arrow('支付货款')}${actor('firm','面包店')}</div></div>`,'贷款扩大融资能力，生产增加实际商品。能否生产更多，还取决于设备、原料、劳动和技术。','这解释了收入与支出的循环，但不表示工资会全部用于消费。储蓄、税收、政府支出、对外交易等也会影响经济。金融资产价格上升也不等同于实际产出增加。')}
${section(5,'利率是成本，但经济中并非只有一种利率','同样一笔 10,000 元、一年期、到期还本的贷款：调节假设年利率，观察单利成本。',`<div class="controls"><label for="interest">假设贷款年利率</label><input id="interest" type="range" min="0" max="10" step="0.5" value="3"><output id="interestValue">3.0%</output></div><div class="knowledge-grid" style="margin-top:15px">${card('借款人','<span id="interestCost" class="money">一年利息 ¥300</span>','不含手续费、税费与分期还款影响。')}${card('储蓄者','存款利率提高时，推迟消费可能更有吸引力。','贷款利率与存款利率通常不同。')}</div><div class="pathway"><span>政策利率</span>→<span>市场融资与银行定价</span>→<span>借贷、储蓄与支出选择</span></div><p class="topic-note">央行直接影响部分短期利率；较长期利率还受到未来利率预期、通胀预期和风险溢价等影响。</p><div class="result-box">名义利率告诉你金额怎样变化；实际利率关注购买力。近似关系：实际利率 ≈ 名义利率 − 通胀率。</div>`,'较高融资成本可能抑制新增借款，但作用存在时滞，不能把利率画成直接控制物价的开关。','做未来借贷决定时，关注的是预期实际利率，需扣除预期通胀；事后衡量购买力时，再使用实际发生的通胀。精确关系为 (1+i)/(1+π)−1。固定利率贷款不一定随政策利率即时调整。')}
${section(6,'先看供需怎么变，再看价格和购买力','通胀可能由需求增加、供给受阻或成本上升等力量共同推动。下面比较三种情况，不把新增货币与涨价机械画等号。',`<div class="switches"><button data-scenario="base" aria-pressed="true">供需同步增长</button><button data-scenario="demand" aria-pressed="false">需求增长更快</button><button data-scenario="supply" aria-pressed="false">供给受阻</button></div><div class="plot"><span class="plot-label">购买需求</span><div id="demandUnits" class="units" aria-hidden="true"></div><output id="demandValue"></output></div><div class="plot"><span class="plot-label">商品供给</span><div id="supplyUnits" class="units goods" aria-hidden="true"></div><output id="supplyValue"></output></div><div id="pricePressure" class="result-box" aria-live="polite"></div><p class="caption">方块是情景示意单位，不是可估算通胀率的模型；价格还受预期、竞争、生产能力等影响。</p><div class="knowledge-grid" style="margin-top:18px">${card('价格水平 vs 涨价速度','价格从 100 涨到 105，再涨到 107.1：通胀率从 5% 降到 2%，价格仍在上涨。')}${card('CPI vs 资产价格','CPI 衡量居民消费的一篮子商品和服务。股票、房产购买价格上涨，不等于 CPI 同幅上涨。')}</div><div class="panel-note">购买力例子：同样 100 元，单价从 10 元涨到 12 元，可购买数量从 10 件降至约 8.33 件。单一商品的例子解释购买力，不能单独证明总体通胀。</div>`,'CPI 是加权的消费价格指标。个人消费结构不同，感受到的涨价幅度也会不同。','居民买房购置资产与消费居住服务需区分；租金等居住服务可能进入 CPI，具体以本地统计口径为准。供给冲击也可能在需求疲弱时推高价格。货币、信用与支出之间的联系受经济环境影响。')}
${section(7,'最后，再用面包店把机制串起来','现在可以连贯阅读，而不会把记账、生产、政策和价格混成一种变化。',`<div class="case-steps"><div class="case-step"><span>1</span><div><b>获批贷款：存款和债务同时增加</b><p>面包店借入 10,000 元，获得支付能力，但净财富没有因此增加。</p></div></div><div class="case-step"><span>2</span><div><b>支付工资：钱换了持有人</b><p>支付 2,000 元工资，面包店剩 8,000 元，员工持有 2,000 元，合计不变。</p></div></div><div class="case-step"><span>3</span><div><b>生产和出售：商品交付，支付回流</b><p>员工购买 100 元面包后，面包店持有 8,100 元，员工持有 1,900 元。</p></div></div><div class="case-step"><span>4</span><div><b>偿还本金：相应贷款与存款减少</b><p>面包店偿还 1,000 元本金，企业与员工合计存款变为 9,000 元，贷款余额为 9,000 元。</p></div></div><div class="case-step"><span>5</span><div><b>下一个决定：利率影响借款，供需影响价格</b><p>融资更贵可能让扩张计划推迟；价格是否上涨，还要看需求、供给与成本，不能从“借过款”直接推出“会通胀”。</p></div></div></div>`,'一张好的经济图，应该让你知道：谁的账户变了、商品有没有增加、哪些结论只在特定条件下成立。')}
<div class="sources"><b>知识依据与延伸阅读</b><p><a href="https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy" target="_blank" rel="noopener">英格兰银行：现代经济中的货币创造</a>（第 1–3 节）<br><a href="https://books.core-econ.org/the-economy/en/index.html" target="_blank" rel="noopener">CORE Econ：《The Economy 2.0》</a>（经济活动、信贷与政策框架）<br><a href="https://www.pearson.com/content/dam/one-dot-com/one-dot-com/hei-samples/business---economics/9781292409481-toc.pdf" target="_blank" rel="noopener">米什金《货币金融学》公开目录</a>（货币、利率与政策的知识组织参考）<br><a href="https://www.stats.gov.cn/zs/tjws/zytjzbqs/jmxxggzs/202409/t20240910_1956353.html" target="_blank" rel="noopener">国家统计局：什么是 CPI</a> · <a href="https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_inflation.en.html" target="_blank" rel="noopener">欧洲央行：什么是通胀</a>（第 6 节）</p></div><p class="footer">全部金额为简化教学示例；未描述任何实际银行的完整账目。基础知识版 · </p></article></div></main>`;
const $=s=>document.querySelector(s);function loan(mode){const v=mode==='after'?'¥10,000':'¥0';for(const id of ['bankLoan','bankDeposit','shopDeposit','shopDebt'])$('#'+id).textContent=v;for(const id of ['before','after','repay'])$('#'+id).setAttribute('aria-pressed',String(id===mode));$('#loanExplain').textContent={before:'发放前：本例的新增贷款和新增存款均为零。',after:'发放后：银行新增贷款资产与存款负债各 10,000 元；面包店的存款资产与债务也各增加 10,000 元。',repay:'假设尚未转出存款，并用其偿还全部本金：本例新增贷款与存款同时归零。没有模拟利息及其他业务。'}[mode]}for(const id of ['before','after','repay'])$('#'+id).onclick=()=>loan(id);
function interest(){const v=+$('#interest').value;$('#interestValue').textContent=v.toFixed(1)+'%';$('#interest').setAttribute('aria-valuetext',v.toFixed(1)+'%，一年利息 '+v*100+' 元');$('#interestCost').textContent='一年利息 ¥'+(v*100).toLocaleString('zh-CN')}$('#interest').oninput=interest;interest();
const scenarios={base:[12,12,'需求与供给都增加：商品变多，支出也增加，不能据此判断价格一定上涨。'],demand:[15,10,'购买需求增长更快：供给短期跟不上，价格可能承受上涨压力。'],supply:[10,7,'供给受阻：即使需求不变，原料短缺、能源涨价等也可能造成价格上涨压力。']};function scenario(k){const[d,s,t]=scenarios[k];$('#demandUnits').innerHTML='<i></i>'.repeat(d);$('#supplyUnits').innerHTML='<i></i>'.repeat(s);$('#demandValue').textContent=d+' 单位';$('#supplyValue').textContent=s+' 单位';$('#pricePressure').textContent=t;document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scenario===k)))}document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>scenario(b.dataset.scenario));scenario('base');
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)document.querySelectorAll('.toc a').forEach(a=>a.classList.toggle('current',a.hash==='#'+e.target.id))},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('.chapter').forEach(s=>observer.observe(s));
